def find_changed_pairs(inputs, outputs):
    """Identify which (input, output) pairs actually differ."""
    changed = []
    for i, (inp, outp) in enumerate(zip(inputs, outputs)):
        if inp != outp:
            changed.append((i, inp, outp))
    return changed

def find_minimal_edit(s_in, s_out):
    """Find the minimal edit from s_in to s_out."""
    # Find first position where strings differ
    pos = -1
    for i, (c1, c2) in enumerate(zip(s_in, s_out)):
        if c1 != c2:
            pos = i
            break

    # If strings are of different length or we found a difference
    if pos == -1:
        if len(s_in) != len(s_out):
            pos = min(len(s_in), len(s_out))
        else:
            return None  # No difference

    # Determine what to replace and what to replace it with
    old_sub = ""
    new_sub = ""

    # Check if it's insertion/deletion vs substitution
    if len(s_in) < len(s_out):
        # Insertion case
        old_sub = ""
        new_sub = s_out[pos]
    elif len(s_in) > len(s_out):
        # Deletion case  
        old_sub = s_in[pos]
        new_sub = ""
    else:
        # Substitution case
        old_sub = s_in[pos]
        new_sub = s_out[pos]

    return (old_sub, new_sub, pos)

def propose_rule_candidates(s_in, s_out):
    """Propose candidate rules from a change."""
    # Simple approach: return the minimal edit as the primary candidate
    edit = find_minimal_edit(s_in, s_out)
    if edit is None:
        return []

    old_sub, new_sub, pos = edit
    # Return specific pattern first, then more general ones
    candidates = []

    # Specific pattern: exact substring match
    if old_sub:
        candidates.append((old_sub, new_sub))

    # General patterns could include longer substrings, but for now we'll keep simple
    return candidates

def apply_rules(strings, rules):
    """Apply a sequence of rules to strings."""
    result = strings[:]
    for pattern, replacement in rules:
        result = [s.replace(pattern, replacement) for s in result]
    return result

def score_rules(inputs, outputs, rules):
    """Score how well rules perform on the corpus."""
    predicted = apply_rules(inputs, rules)
    correct = sum(1 for p, o in zip(predicted, outputs) if p == o)
    return correct / len(inputs)

def find_over_applications(inputs, outputs, rules):
    """Find cases where rules incorrectly modify strings that should remain unchanged."""
    predicted = apply_rules(inputs, rules)
    over_apps = []
    for i, (inp, outp, pred) in enumerate(zip(inputs, outputs, predicted)):
        if pred != outp and inp != outp:  # Rule modified something that shouldn't change
            over_apps.append((i, inp, pred))
    return over_apps

def simulate_rule_chain(s, rules):
    """Simulate applying rules to a single string step by step."""
    trace = []
    current = s
    for pattern, replacement in rules:
        prev = current
        current = current.replace(pattern, replacement)
        trace.append({
            'pattern': pattern,
            'replacement': replacement,
            'before': prev,
            'after': current
        })
    return trace

def build_proxy_rules(pattern, replacement, proxy="__X__"):
    """Create proxy rules to prevent counterfeeding."""
    pre_rule = (pattern, proxy)
    post_rule = (proxy, replacement)
    return (pre_rule, post_rule)

